<script setup lang="ts">import{computed,onMounted,ref}from"vue";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BaseMetricCard from"@/components/base/BaseMetricCard.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import BasePagination from"@/components/base/BasePagination.vue";import LibraryCopyDialog from"@/components/library/LibraryCopyDialog.vue";import{libraryCopyRepository}from"@/domain/library/repository";import type{LibraryCopyRecord}from"@/domain/library/records";const items=ref<LibraryCopyRecord[]>([]),total=ref(0),borrowed=ref(0),loading=ref(true),error=ref(""),page=ref(1),pages=ref(1),search=ref(""),status=ref(""),dialogOpen=ref(false),editing=ref<LibraryCopyRecord|null>(null);const filtered=computed(()=>items.value.filter(item=>{const q=search.value.toLocaleLowerCase("pt-PT");const title=item.expand?.titulo?.titulo||"";const location=item.localizacao||"";return(!q||`${title} ${location}`.toLocaleLowerCase("pt-PT").includes(q))&&(!status||(status==="borrowed"?item.emprestado:!item.emprestado))}));async function load(){loading.value=true;error.value="";try{const[result,count]=await Promise.all([libraryCopyRepository.list({page:page.value,perPage:30,sort:"-updated",expand:"titulo,formato,tipo_edicao"}),libraryCopyRepository.count("emprestado = true")]);items.value=result.items;total.value=result.totalItems;pages.value=result.totalPages||1;borrowed.value=count}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}function create(){editing.value=null;dialogOpen.value=true}function edit(copy:LibraryCopyRecord){editing.value=copy;dialogOpen.value=true}async function saved(){dialogOpen.value=false;editing.value=null;await load()}onMounted(load)</script><template><BasePageHeader eyebrow="Coleção física" title="Biblioteca" description="Exemplares, localização e empréstimos."><template #actions><button class="button button-primary" type="button" @click="create">＋ Novo exemplar</button></template></BasePageHeader><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><section class="stats-grid compact-stats"><BaseMetricCard icon="▤" label="Exemplares" :value="total" detail="na coleção"/><BaseMetricCard icon="↗" label="Emprestados" :value="borrowed" detail="fora da coleção" tone="amber"/><BaseMetricCard icon="◇" label="Disponíveis" :value="Math.max(0,total-borrowed)" detail="na coleção" tone="cyan"/></section><section class="panel library-filters" aria-labelledby="library-filters-title"><h2 id="library-filters-title">Pesquisar exemplares</h2><label class="form-field"><span>Pesquisa</span><input v-model.trim="search" type="search" placeholder="Título ou localização"/></label><label class="form-field"><span>Estado</span><select v-model="status"><option value="">Todos</option><option value="available">Disponíveis</option><option value="borrowed">Emprestados</option></select></label></section><p v-if="loading" class="page-loading" aria-live="polite">A carregar exemplares…</p><BaseEmptyState v-else-if="!filtered.length" icon="▤" title="Sem exemplares" description="Regista as cópias físicas e digitais que possuis."/><div v-else class="table-wrap"><table><thead><tr><th>Título</th><th>Formato</th><th>Edição</th><th>Localização</th><th>Estado</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><strong>{{item.expand?.titulo?.titulo||'Título desconhecido'}}</strong><small v-if="item.expand?.titulo?.ano">{{item.expand.titulo.ano}}</small></td><td>{{item.expand?.formato?.nome||'—'}}</td><td>{{item.expand?.tipo_edicao?.nome||'—'}}</td><td>{{item.localizacao||'—'}}</td><td>{{item.emprestado?'Emprestado':'Disponível'}}</td><td><button class="button button-secondary" type="button" @click="edit(item)">Editar</button></td></tr></tbody></table></div><BasePagination :page="page" :pages="pages" label="Paginação dos exemplares" @change="page=$event;load()"/><LibraryCopyDialog :open="dialogOpen" :copy="editing" @close="dialogOpen=false" @saved="saved"/></template>
